import csv
import io
import re


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=";",
        quotechar='"',
        doublequote=True,
    ))

    expected_width = 4
    nonblank = [
        i for i, row in enumerate(records)
        if any(value.strip() for value in row)
    ]
    if not nonblank:
        return {"columns": [], "rows": []}

    header_index = nonblank[0]
    candidates = []
    for i in nonblank:
        row = records[i]
        if re.fullmatch(r"[0-9]{4}", row[0].strip()):
            if candidates:
                header_index = candidates[-1]
            break
        if len(row) == expected_width:
            candidates.append(i)
    else:
        if candidates:
            header_index = candidates[0]

    columns = records[header_index][:]
    rows = records[header_index + 1:]
    width = max([expected_width, len(columns)] + [len(row) for row in rows])

    used_names = set(columns)
    while len(columns) < width:
        name = f"extra_{len(columns) + 1}"
        while name in used_names:
            name += "_"
        columns.append(name)
        used_names.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
